@import url('https://fonts.googleapis.com/css2?family=JetBrains+Mono:wght@400;500;600;700&display=swap');

/* Microsoft DNA — fluent four-square, segoe clarity */
.theme-microsoft-dna {
  --bg: oklch(1.000 0 0);
  --surface: oklch(0.962 0.002 67.8);
  --surface-2: oklch(0.935 0.002 67.8);
  --fg: oklch(0.240 0.002 67.7);
  --fg-muted: oklch(0.483 0.004 67.7);
  --accent: oklch(0.568 0.167 251.3);
  --accent-fg: oklch(1.000 0 0);
  --accent-2: oklch(0.510 0.165 142.7);
  --line: oklch(0.941 0.003 67.8);
  --success: oklch(0.523 0.135 144.2);
  --warning: oklch(0.768 0.158 81.3);
  --danger: oklch(0.548 0.194 22.2);
  --radius: 0.25rem;
  --radius-sm: 0.25rem;
  --radius-lg: 0.5rem;
  --radius-pill: 9999px;
  --shadow-1: 0 1px 2px oklch(0 0 0 / 8%);
  --shadow-2: 0 6px 20px -8px oklch(0 0 0 / 15%);
  --shadow-3: 0 20px 50px -16px oklch(0 0 0 / 20%);
  --glow: 0 0 0 1px color-mix(in oklab, var(--accent) 45%, transparent);
  --border-width: 1px;
  --blur-amount: 0px;
  --font-display: "Segoe UI", "Selawik", sans-serif;
  --font-body: "Segoe UI", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --tracking-display: 0em;
  --label-transform: none;
  --label-tracking: 0.02em;

  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-microsoft-dna h1,
.theme-microsoft-dna h2,
.theme-microsoft-dna h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
}

/* signature */
.theme-microsoft-dna h1 { font-weight: 600; }
.theme-microsoft-dna h2::before { content: ""; display: inline-block; width: 0.55em; height: 0.55em; margin-right: 0.4em; background: conic-gradient(#F25022 0 25%, #7FBA00 0 50%, #FFB900 0 75%, #00A4EF 0 100%); }
.theme-microsoft-dna button { font-weight: 600; }

/* depth */
.theme-microsoft-dna thead th { background: var(--surface); border-bottom: 1px solid var(--line); font-weight: 600; font-size: 0.8125rem; }
.theme-microsoft-dna td { border-bottom: 1px solid var(--surface-2); }
.theme-microsoft-dna tbody tr:hover { background: var(--surface); }
.theme-microsoft-dna a { color: var(--accent); text-decoration: none; }
.theme-microsoft-dna a:hover { text-decoration: underline; }
.theme-microsoft-dna input, .theme-microsoft-dna select, .theme-microsoft-dna textarea { background: var(--bg); border: 1px solid oklch(0.62 0.004 67.7); border-bottom-color: oklch(0.45 0.004 67.7); border-radius: var(--radius); transition: box-shadow 100ms ease; }
.theme-microsoft-dna input:focus-visible, .theme-microsoft-dna select:focus-visible, .theme-microsoft-dna textarea:focus-visible { outline: none; border-color: var(--line); box-shadow: inset 0 -2px 0 0 var(--accent); }
.theme-microsoft-dna kbd { font-family: var(--font-body); background: var(--surface); border: 1px solid var(--line); border-bottom-width: 2px; border-radius: var(--radius-sm); padding: 0.1em 0.45em; font-size: 0.8em; }
.theme-microsoft-dna button:focus-visible { outline: 2px solid var(--fg); outline-offset: 1px; }
.theme-microsoft-dna button { transition: background 100ms ease, transform 100ms ease; }
.theme-microsoft-dna button:active { transform: scale(0.98); }
.theme-microsoft-dna ::selection { background: oklch(0.568 0.167 251.3 / 30%); }
.theme-microsoft-dna ::-webkit-scrollbar { width: 10px; height: 10px; }
.theme-microsoft-dna ::-webkit-scrollbar-track { background: var(--surface); }
.theme-microsoft-dna ::-webkit-scrollbar-thumb { background: oklch(0.6 0 0 / 55%); border-radius: var(--radius-pill); }
.theme-microsoft-dna .label-caps { font-size: 0.75rem; color: var(--fg-muted); }
.theme-microsoft-dna .themed-border { border-color: var(--line); box-shadow: var(--shadow-1); }

/* alt mode: Fluent dark — #201f1e neutrals, lighter accent for contrast */
.theme-microsoft-dna.alt-mode {
  --bg: oklch(0.220 0.002 67.8);
  --surface: oklch(0.260 0.002 67.8);
  --surface-2: oklch(0.300 0.002 67.8);
  --fg: oklch(0.950 0.002 67.8);
  --fg-muted: oklch(0.700 0.004 67.8);
  --line: oklch(1 0 0 / 14%);
  --accent: oklch(0.680 0.145 250);
  --accent-fg: oklch(0.130 0 0);
  --shadow-1: 0 2px 6px oklch(0 0 0 / 45%);
  --shadow-2: 0 8px 24px oklch(0 0 0 / 55%);
  --shadow-3: 0 24px 56px oklch(0 0 0 / 65%);
}
.theme-microsoft-dna.alt-mode input, .theme-microsoft-dna.alt-mode select, .theme-microsoft-dna.alt-mode textarea { background: var(--surface); border-color: oklch(1 0 0 / 20%); border-bottom-color: oklch(1 0 0 / 35%); }
.theme-microsoft-dna.alt-mode button:focus-visible { outline-color: var(--fg); }
.theme-microsoft-dna.alt-mode td { border-bottom-color: var(--surface-2); }

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);

  /* Full app surface: sidebar, charts, app-level font + shadow + tracking vars.
     These are what real products (shadcn full kit, RootCX-style UI kits) consume —
     without them a retrofit looks half-themed. */
  --sidebar: var(--surface-2);
  --sidebar-foreground: var(--fg);
  --sidebar-primary: var(--accent);
  --sidebar-primary-foreground: var(--accent-fg);
  --sidebar-accent: color-mix(in oklab, var(--accent) 12%, var(--surface-2));
  --sidebar-accent-foreground: var(--fg);
  --sidebar-border: var(--line);
  --sidebar-ring: var(--accent);

  --chart-1: var(--accent);
  --chart-2: var(--accent-2);
  --chart-3: var(--success);
  --chart-4: var(--warning);
  --chart-5: var(--danger);

  --font-sans: var(--font-body);
  --font-heading: var(--font-display);
  --font-serif: var(--font-display);

  --shadow-2xs: var(--shadow-1);
  --shadow-xs: var(--shadow-1);
  --shadow-sm: var(--shadow-1);
  --shadow: var(--shadow-2);
  --shadow-md: var(--shadow-2);
  --shadow-lg: var(--shadow-3);
  --shadow-xl: var(--shadow-3);
  --shadow-2xl: var(--shadow-3);

  --tracking-normal: 0em;
}

/* Base experience: make the theme own the canvas and native elements even in
   apps that never adopted semantic classes. Scoped to the theme wrapper. */
[class*="theme-"] {
  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}
[class*="theme-"] :is(h1, h2, h3, h4) { font-family: var(--font-display); }
[class*="theme-"] :is(code, pre, kbd, samp) { font-family: var(--font-mono); }
[class*="theme-"] ::selection { background: color-mix(in oklab, var(--accent) 30%, transparent); }

/* OPT-IN HARD MODE — add "sf-enforce" beside the theme class when the host app
   bakes font/shadow/radius literals into its compiled utilities (a var bridge
   cannot beat a literal). Targeted !important, fonts and surfaces only. */
[class*="theme-"].sf-enforce { font-family: var(--font-body) !important; }
[class*="theme-"].sf-enforce :is(h1, h2, h3, h4, [class*="font-heading"], [class*="text-2xl"], [class*="text-3xl"], [class*="text-4xl"], [class*="text-5xl"]) {
  font-family: var(--font-display) !important;
  letter-spacing: var(--tracking-display) !important;
}
[class*="theme-"].sf-enforce :is(button, [role="button"]) { font-family: var(--font-ui, var(--font-body)) !important; }
[class*="theme-"].sf-enforce :is(code, pre, kbd) { font-family: var(--font-mono) !important; }
[class*="theme-"].sf-enforce :is(.bg-card, [class*="card"]) {
  box-shadow: var(--shadow-2) !important;
  border-radius: var(--radius-lg) !important;
  border: var(--border-width) solid var(--line) !important;
}
[class*="theme-"].sf-enforce :is([class*="shadow-sm"], [class*="shadow-md"]) { box-shadow: var(--shadow-1) !important; }
[class*="theme-"].sf-enforce :is([class*="shadow-lg"], [class*="shadow-xl"]) { box-shadow: var(--shadow-3) !important; }
